import { Box, ChakraProvider, Flex, Theme } from "@chakra-ui/react";
import { useState } from "react";
import { BrowserRouter, useSearchParams } from "react-router-dom";
import { StandaloneHeader } from "./components/StandaloneHeader";
import { InspectorCore } from "./Inspector/InspectorCore";
import { resolveStandaloneProjectUrl } from "./resolveProjectUrl";
import { system } from "./theme";

/**
 * Standalone HTML entry point used by main.tsx.
 * Wraps the Inspector core with routing, theme, and the standalone UI shell.
 */
export const App = () => (
  <BrowserRouter>
    <ChakraProvider value={system}>
      <Theme appearance="light">
        <AppContent />
      </Theme>
    </ChakraProvider>
  </BrowserRouter>
);

// Inner component so useSearchParams (router hook) can run inside BrowserRouter.
// Keeps the standalone reactive to back/forward and programmatic URL changes.
const AppContent = () => {
  const [containerWidth, setContainerWidth] = useState("1000px");
  const [searchParams] = useSearchParams();

  // Inspector build is served from the Rasa server, so window.location.origin
  // already contains the correct host and specified --port 5007 e.g. http://localhost:5007.
  // Breaks in dev mode as origin is Vite dev server e.g. http://localhost:5173.
  // Therefore in dev mode default to hardcoded http://localhost:5005.
  const resolvedProjectUrl = resolveStandaloneProjectUrl(searchParams);
  const resolvedChannel = searchParams.get("channel") ?? undefined;
  // Read auth token from URL (passed by CLI with rasa inspect --auth-token my-secret-token)
  const resolvedAuthToken = searchParams.get("token") ?? undefined;
  // Read sender from URL so the inspector can display a previously-saved conversation
  // (e.g. the eval suite opens inspect.html?sender=<conversation_id>).
  const resolvedSender = searchParams.get("sender") ?? undefined;

  return (
    <Flex
      direction="column"
      css={{
        backgroundColor: "bg.subtle",
        backgroundSize: "cover",
        height: "100vh",
        alignItems: "stretch",
      }}
    >
      <StandaloneHeader />
      <Box
        flex={1}
        p="4"
        position="relative"
        css={{
          maxWidth: "100%",
          minWidth: "618px",
          width: containerWidth,
          transition: "width 0.4s ease",
          height: "calc(100% - 3rem)",
          margin: "0 auto",
        }}
      >
        <InspectorCore
          projectUrl={resolvedProjectUrl}
          channel={resolvedChannel}
          authToken={resolvedAuthToken}
          sessionId={resolvedSender}
          onInspectModeChange={(inspect) => setContainerWidth(inspect ? "100%" : "1000px")}
          isEmbedded={false}
          botDataEndpoint="/data"
          singleSessionMode
        />
      </Box>
    </Flex>
  );
};
